			        var sSrvcTypeSeCd  = util.DataSet.getValue(app, "dsCaseExcnList", i, "SRVC_TYPE_SE_CD");      //서비스유형구분코드

			        var sRowType       = util.DataSet.getRowStateString(app, "dsCaseExcnList", i);

			        var sMsg = "실행목록의 " + (i+1) + "번째 실행상세 데이터에서";

