			function setFilterProgrmDs() {

			    var nIdx = util.Grid.getIndex(app, "grdCaseExcnList");

			    var sCaseMngNo    = util.Grid.getCellValue(app, "grdCaseExcnList", "CASE_MNG_NO"        , nIdx); //사례관리번호
			    var sCaseMngOdrno = util.Grid.getCellValue(app, "grdCaseExcnList", "CASE_MNG_ODRNO"     , nIdx); //사례관리차수
			    var sSrvcPvsnNo   = util.Grid.getCellValue(app, "grdCaseExcnList", "SRVC_PVSN_NO"       , nIdx); //서비스제공번호
			    var sResrceNo     = util.Grid.getCellValue(app, "grdCaseExcnList", "RESRCE_NO"          , nIdx); //자원번호
			    var sRowIdx       = util.Grid.getCellValue(app, "grdCaseExcnList", "CASE_EXCN_ROW_INDEX", nIdx);

			    var objDs = app.lookup("dsProgramList");
			    var sCondition = null;
			        sCondition = "CASE_MNG_NO == '" + sCaseMngNo +"' && CASE_MNG_ODRNO == '" + sCaseMngOdrno + "' && RESRCE_NO == '" + sResrceNo + "'";

			    if(util.Grid.getRowState(app, "grdCaseExcnList", nIdx) == cpr.data.tabledata.RowState.INSERTED) {
			        sCondition = sCondition + " && CASE_EXCN_ROW_INDEX == '" + sRowIdx + "'";
			    } else {
			        sCondition = sCondition + " && SRVC_PVSN_NO == '" + sSrvcPvsnNo + "'"; 
			    }
			//    console.log("필터조건 : " + sCondition);

			    objDs.clearFilter();
			    objDs.setFilter(sCondition);
			}

			function sendData(nIndex) {

			    if(nIndex < 0 || ValueUtil.isNull(nIndex)) {
			        return;
			    }

			    var sendResrceNo = util.DataSet.getValue(app, "dsCaseExcnList", nIndex, "RESRCE_NO");
			    var sendPvsnNo   = util.DataSet.getValue(app, "dsCaseExcnList", nIndex, "SRVC_PVSN_NO");
			//    console.log("자원번호 : " + sendResrceNo);
			//    console.log("서비스제공번호 : " + sendPvsnNo);

			    if(vsAppId != null) {
			        if(vcEmbDefInfo.hasAppMethod("srvcCall")){
			            vcEmbDefInfo.callAppMethod("srvcCall", sendResrceNo, sendPvsnNo);
			        }
			    }
			}

