			/*
			 * 사용자 정의 컨트롤에서 beforeDelete 이벤트 발생 시 호출.
			 * 삭제버튼 클릭전 호출 이벤트(행 삭제전에 체크할 비지니스 로직이 있는 경우 사용)
			 * 실행목록
			 */
			function onComBtnGrid5BeforeDelete(e){

			    var comBtnGrid5 = e.control;

			    var nIdx = util.Grid.getIndex(app, "grdCaseExcnList");

			    var sSrvcGrPvsnYn = util.Grid.getCellValue(app, "grdCaseExcnList", "SRVC_GR_PVSN_YN"  , nIdx); //서비스집단제공여부
			    if(sSrvcGrPvsnYn == "Y") {
			        util.Msg.alert(app, "집단서비스는 '집단서비스등록'에서 삭제 해주시기 바랍니다.");
			        return false;
			    }
			    
			    var sUnregiCaseYn = util.Grid.getCellValue(app, "grdCaseExcnList", "UNREGI_CASE_YN"  , nIdx); //서비스집단제공여부
			    if(sUnregiCaseYn == "Y" && sUserNo != "EN2023022300012") { // 점검 후 삭제
			        util.Msg.alert(app, "미등록사례는 '미등록사례지원'에서 삭제 해주시기 바랍니다.");
			        return false;
			    }

			    var sEndDate      = util.Grid.getCellValue(app, "grdCaseExcnList", "SRVC_PVSN_END_YMD", nIdx); //서비스제공종료일자
			    var bCheckVal = true;

			    if(!ValueUtil.isNull(sEndDate)) {
			        if(!ValueUtil.isNull(sDdlnCrtrYmd)) {

			            //1.마감기준일자 vs 당일 비교
			            if(sDdlnCrtrYmd > vsToday) {
			                if(sEndDate.substring(0,6) < sDdlnYm) {
			                    bCheckVal = false;
			                }
			            } else {
			                if(sEndDate.substring(0,6) <= sDdlnYm) {
			                    bCheckVal = false;
			                }
			            }

			            if(util.Grid.getRowState(app, "grdCaseExcnList", nIdx) != cpr.data.tabledata.RowState.INSERTED) {
			                if(!bCheckVal) {
			                    util.Msg.alert(app, "월마감이 완료되어 삭제가 불가능합니다.");
			                    return false;
			                }
			            }
			        }
			    }

			    var sCaseMngNo    = util.Grid.getCellValue(app, "grdCaseExcnList", "CASE_MNG_NO"        , nIdx); //사례관리번호
			    var sCaseMngOdrno = util.Grid.getCellValue(app, "grdCaseExcnList", "CASE_MNG_ODRNO"     , nIdx); //사례관리차수
			    var sSrvcPvsnNo   = util.Grid.getCellValue(app, "grdCaseExcnList", "SRVC_PVSN_NO"       , nIdx); //서비스제공번호
			    var sResrceNo     = util.Grid.getCellValue(app, "grdCaseExcnList", "RESRCE_NO"          , nIdx); //자원번호
			    var sRowIdx       = util.Grid.getCellValue(app, "grdCaseExcnList", "CASE_EXCN_ROW_INDEX", nIdx);

			//    if(util.Grid.getRowState(app, "grdCaseExcnList", nIdx) == cpr.data.tabledata.RowState.INSERTED) {
			        for(var i=util.Grid.getRowCount(app, "grdExcnProgMainList"); i>=0; i--) {
			            if(util.Grid.getCellValue(app, "grdExcnProgMainList", "CASE_MNG_NO"        , i) == sCaseMngNo    &&
			               util.Grid.getCellValue(app, "grdExcnProgMainList", "CASE_MNG_ODRNO"     , i) == sCaseMngOdrno &&
			               util.Grid.getCellValue(app, "grdExcnProgMainList", "SRVC_PVSN_NO"       , i) == sSrvcPvsnNo   &&
			               util.Grid.getCellValue(app, "grdExcnProgMainList", "RESRCE_NO"          , i) == sResrceNo     &&
			               util.Grid.getCellValue(app, "grdExcnProgMainList", "CASE_EXCN_ROW_INDEX", i) == sRowIdx) {
			                util.Grid.deleteRow(app, "grdExcnProgMainList", i);
			            }
			        }
			//    }

			    setDsProgMainRowCnt();

			    app.lookup("grpExcnProgMainList").redraw();    
			}

